        if not math.isfinite(neg_abs):
            raise ValueError(
                "binary_cross_entropy_with_logits intermediate must be"
                " finite"
            )
        exp_term = math.exp(neg_abs)
        if not math.isfinite(exp_term):
            raise ValueError(
                "binary_cross_entropy_with_logits intermediate must be"
                " finite"
